// 時刻表 ①c：本地 plugin tt-notice 的 build（①b①c 契約 §5.10.1）。
// 產生 permissions/autogenerated/**（進版控）；Android target 時把 tauri-api 複製進 android/.tauri/tauri-api（gitignore）
// 並送 cargo:android_library_path，tauri-build 據此產生 tauri.settings.gradle——gen/android 一個字都不動。

const COMMANDS: &[&str] = &[
    "post",
    "remove",
    "take_pending",
    "ack_pending",
    "schedule_reminder",
    "cancel_reminder",
    "status",
    // 旅客筆記 ⑤：分享進收件匣（取＋確認兩段）
    "take_shared",
    "ack_shared",
    // addPluginListener 走 plugin:tt-notice|register_listener（notification 2.3.3 api-iife.js）
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
